import { createState, collectCoin } from '../logic/score.js';

const SPEED = 200;
const KEY_SETTLE_MS = 100;

export class GameScene extends Phaser.Scene {
  constructor() {
    super('game');
    this.state = createState();
    this.held = { left: false, right: false, up: false, down: false };
  }

  create() {
    this.player = this.add.rectangle(400, 300, 24, 24, 0xffcc00);
    this.physics.add.existing(this.player);
    this.coins = this.physics.add.group();
    for (let i = 0; i < 8; i++) this.coins.add(this.add.circle(80 + i * 90, 120, 8, 0xffffff));
    this.physics.add.overlap(this.player, this.coins, (_player, coin) => {
      coin.destroy();
      this.state = collectCoin(this.state);
    });

    // leading so a press moves at once, trailing to settle the final key state
    // after a held key's auto-repeat stops.
    this.settleVelocity = _.debounce(() => {
      const body = this.player.body;
      body.setVelocity(0);
      if (this.held.left) body.setVelocityX(-SPEED);
      if (this.held.right) body.setVelocityX(SPEED);
      if (this.held.up) body.setVelocityY(-SPEED);
      if (this.held.down) body.setVelocityY(SPEED);
    }, KEY_SETTLE_MS, { leading: true, trailing: true });

    for (const key of Object.keys(this.held)) {
      const code = key.toUpperCase();
      this.input.keyboard.on(`keydown-${code}`, () => this.setHeld(key, true));
      this.input.keyboard.on(`keyup-${code}`, () => this.setHeld(key, false));
    }
  }

  setHeld(key, isDown) {
    this.held[key] = isDown;
    this.settleVelocity();
  }
}

